INSERT INTO @HBES (HBE)
SELECT TRY_CAST(value AS INT) FROM STRING_SPLIT(@Lista, ',');

--SELECT COUNT(*) FROM @HBES

SELECT 
    A.id_Alo		AS [HBE],
	AUC.id_AUC      AS [ID_AUC]
FROM 
				Tbl_Alojamiento					A
	LEFT JOIN	vwQlik_JP_Externos				AE		ON (AE.AlE_Cod = A.Id_Alo AND AE.AlE_Prov = 'J107')
	LEFT JOIN	Tbl_AlojamientoUnicoCliente		AUC		ON AUC.AUC_JPCode = AE.ALU_JPCode
	LEFT JOIN	Tbl_AucNEau						ANE		ON ANE.id_AUC = AUC.id_AUC
	LEFT JOIN	Tbl_EtiquetaAlojaUnicoCliente	EAU		ON EAU.id_EAU = ANE.id_EAU
	LEFT JOIN	Tbl_IdiNEtiqueta				INE		ON (EAU.id_EAU = INE.id_EAU AND INE.id_Idi = 'es')
WHERE 
	1 = 1
	AND A.Id_Alo IN (SELECT * FROM @HBES)
	AND (AE.ALU_JPCode IS NOT NULL)	
	--AND (AUC.id_AUC IS NULL)
